def dealnnoy_num(n, k):
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    # Base cases
    for i in range(n + 1):
        for j in range(k + 1):
            if i == 0 and j == 0:
                dp[i][j] = 1
            elif i == 0:
                dp[i][j] = dp[i][j - 1]
            elif j == 0:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = dp[i][j - 1] + dp[i - 1][j - 1] + dp[i - 1][j]

    return dp[n][k]
```

