def min_cost(cost, m, n):
    # Initialize the first column with the cost of the first row
    for i in range(1, m + 1):
        cost[i][0] += cost[i - 1][0]

    # Fill the rest of the matrix with the minimum cost to reach that position
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            cost[i][j] += min(cost[i - 1][j], cost[i][j - 1])

    # The minimum cost to reach (m, n) is in cost[m][n]
    return cost[m][n]
