def find_triplet_array(arr, n, sum):
    # Remove duplicates
    arr = list(dict.fromkeys(arr))
    # Iterate over the array
    for i in range(n):
        # Two-pointer technique
        low = i + 1
        high = n - 1
        while low < high:
            # Calculate the sum of the triplet
            current_sum = arr[i] + arr[low] + arr[high]
            # Check if the current sum is equal to the target sum
            if current_sum == sum:
                return (arr[i], arr[low], arr[high])
            # If the current sum is less than the target sum, move the lower pointer to the right
            elif current_sum < sum:
                low += 1
            # If the current sum is greater than the target sum, move the higher pointer to the left
            else:
                high -= 1
    return None
```

