def last(nums, target, start = 0, end = -1):
    if start == -1: start = 0
    if nums[start] == target:
        return start
    while start <= end:
        mid = start + (end - start) // 2
        if nums[mid] == target:
            start = mid + 1
        elif nums[mid] < target:
            start = mid + 1
        else:
            end = mid - 1
    return -1
```

