def lbs(arr):
    n = len(arr)
    # Initialize left and right LIS arrays and tc (top concept) array
    L = [1] * n
    R = [1] * n
    tc = [1] * n

    # Calculating the top concept array
    for i in range(1, n):
        tc[i] = tc[i-1] + 1 if arr[i] > arr[i-1] else 1

    # Finding longest increasing subsequence for all i
    for i in range(n-1, -1, -1):
        for j in range(i):
            if arr[i] > arr[j] and tc[i] < (1 + tc[j]):
                tc[i] = tc[j] + 1

    # Finding the longer of the left and right LIS
    # and storing the result in the result array
    result = []
    for i in range(0, n):
        for j in range(i):
            if L[i] == L[j] + R[j] and tc[i] < tc[j] + 1:
                result.append(arr[i])

    return max(result)
