        for j in range(i+1, n):
            if nums[j] < nums[i] and decreasing[j] + 1 > decreasing[i]:
                decreasing[i] = decreasing[j] + 1

    # Find the maximum length of the bitonic subsequence
    max_length = 0
    for i in range(n):
        max_length = max(max_length, increasing[i] + decreasing[i] - 1)

