def min_coins(coins, value,dp={}):
    if value in dp:
        return dp[value]
    if value == 0:
        return 0
    if not coins:
        return float('inf')

    min_count = float('inf')
    for coin in coins:
        if coin > value:
            continue
        count = min_coins(coins, value - coin, dp) + 1
        min_count = min(min_count, count)

    dp[value] = min_count
