from itertools import combinations

def coin_partitions(n):
    """Generate all coin partitions of n."""
    if n == 0:
        return [[0]]
    partitions = []
    for i in range(1, n + 1):
        for sub_partition in coin_partitions(n - i):
            partitions.append(sub_partition + [i])
    return partitions

def lobb_num(alpha, beta, n):
    """Compute the Lobb number L_{\alpha, \beta} for given \(\alpha\), \(\beta\), and \(n\)."""
    partitions = coin_partitions(n)
    lobb_count = 0
    for part in partitions:
        # Calculate the union of the subsets of part and the remaining elements
        union_set = set(part)
        remaining_elements = set(range(n + 1))[len(part):]

        # Find subsets of union_set that have an average of alpha and beta
        for k in range(1, len(part) + 1):
            for subset in combinations(union_set, k):
                sub_sum = sum(subset)
                sub_avg = sub_sum / k
                if alpha <= sub_avg <= beta:
                    remaining_subset = remaining_elements - subset
                    if sum(remaining_subset) == 0:
                        lobb_count += 1

