def maxAverageOfPath(matrix, n):
    # Initialize the DP table
    dp = [[0] * n for _ in range(n)]

    # Fill the DP table
    for i in range(n):
        for j in range(n):
            # Initialize the average with the value in the current cell
            dp[i][j] = matrix[i][j]

            # Try all possible cell values as the starting point of the path
            for k in range(-1, 2):
                for l in range(-1, 2):
                    # Skip the current cell
                    if k == 0 and l == 0:
                        continue
                    # Calculate the number of steps and the sum of the path
                    steps = 1
                    path_sum = matrix[i][j]
                    for x in range(i+k, i+k+1):
                        for y in range(j+l, j+l+1):
                            if 0 <= x < n and 0 <= y < n:
                                steps += 1
                                path_sum += matrix[x][y]
                    # Update the DP value
                    dp[i][j] = max(dp[i][j], path_sum / steps)

    # Find the maximum average of all paths
    max_avg = 0
    for i in range(n):
        for j in range(n):
            max_avg = max(max_avg, dp[i][j])

    return max_avg
