def super_seq(str1, str2, m, n):
    # Create dp array for storing lengths of LCS
    dp = [[-1]*(n+1) for _ in range(m+1)]

    # Function to return length of LCS of str1[0..m-1] and str2[0..n-1]
    def lcs(i, j):
        if i == 0 or j == 0:
            return 0
        if dp[i][j] != -1:
            return dp[i][j]
        if str1[i-1] == str2[j-1]:
            dp[i][j] = lcs(i-1, j-1) + 1
        else:
            dp[i][j] = max(lcs(i-1, j), lcs(i, j-1))
        return dp[i][j]

    # Return the sum of lengths of longest common prefix
    lcs1 = lcs(m, n)
    return lcs1 + m + n
```
