def rencontres_number(n, k):
    # Dynamic programming approach to find the nth rencontres number
    # Initialize a 2D list with all zeros
    dp = [[0] * (k+1) for _ in range(n+1)]

    # Base cases
    for i in range(n+1):
        for j in range(k+1):
            if i == 0 or j == 0:
                dp[i][j] = 0
            elif i == 1 and j == 1:
                dp[i][j] = 1
            elif i == 2:
                if j == 2:
                    dp[i][j] = dp[i-1][j] + dp[i-2][j-1]
                else:
                    dp[i][j] = dp[i-1][j]
            else:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]

    return dp[n][k]
```

