def sum_Of_Primes(n):
    def is_prime(number):
        """Returns True if the number is prime, False otherwise."""
        if number <= 1:
            return False
        if number <= 3:
            return True
        if number % 2 == 0 or number % 3 == 0:
            return False
        i = 5
        while i * i <= number:
            if number % i == 0 or number % (i + 2) == 0:
                return False
            i += 6
        return True

    sum_of_primes = 0
    for num in range(1, n + 1):
        if is_prime(num):
            sum_of_primes += num
    return sum_of_primes

