def min_coins(coins, value, ans):
    # If value is 0, return the number of coins used
    if value == 0:
        return ans
    # If value is negative or no coins left, return maximum possible value
    if value < 0 or len(coins) == 0:
        return float('inf')
    # Choose the minimum number of coins by trying all possible coins
    one = min_coins(coins, value - coins[0], ans + 1)
    two = min_coins(coins, value, ans)
    # Return the minimum of the two options
    return min(one, two)
