def dealnnoy_num(n, k):
    # Create a table to store values of delannoy numbers
    table = [[0] * (k + 1) for _ in range(n + 1)]

    # Initialize the first row and the first column of the table
    for i in range(k + 1):
        table[0][i] = 1
    for j in range(n + 1):
        table[j][0] = 1

    # Fill the table using the recurrence relation
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            table[i][j] = table[i - 1][j - 1] + table[i][j - 2] + table[i - 2][j - 1]

    # The nth delannoy number is stored in the table[n][k]
    return table[n][k]
```

