def dealnnoy_num(n, k):
    # Define the base cases
    if n == 0:
        return 1
    if k == 0:
        return 1
    if k == 1:
        return 2
    if k == 2:
        return 3

    # Initialize the list to store delannoy number values
    dp = [0] * (n + 1)
    dp[0] = 1
    dp[1] = 1
    dp[2] = 2
    dp[3] = 3

    # Fill the dp table
    for i in range(4, n + 1):
        for j in range(k + 1):
            if i == j:
                dp[i] += dp[i - 1] + dp[i - 2] + dp[i - k]
            elif i > j:
                dp[i] += dp[i - 1] + dp[i - 2] + dp[i - k] + dp[i - k - 1]

    # Return the nth delannoy number
    return dp[n]
