def dealnnoy_num(nesting, depth):
    # Base case: if nesting depth reaches n, return 1 if depth is even, otherwise 0
    if depth == n:
        return 1 if nesting % 2 == 0 else 0
    # Recursive case: sum of delannoy numbers for all valid nesting depths from depth+1 to n
    return sum(dealnnoy_num(nesting + 1, depth + 1) + dealnnoy_num(nesting + 1, depth) + dealnnoy_num(nesting - 1, depth + 1) + dealnnoy_num(nesting - 1, depth) for nesting in range(depth + 1))
