    if not (n > 0 and d > 0):
        raise ValueError("n and d must be positive integers.")

    # Base cases: dealnnoy(0, d) and dealnnoy(n, 0)
    if n == 0 and d == 0:
        return 1
    if n == 0 and d != 0:
        return 0
    if n != 0 and d == 0:
        return 0

