    start, end = 0, len(arr) - 1

    while start <= end:
        mid = (start + end) // 2
        if arr[mid] == extra_element:
            end = mid - 1
        else:
            if arr[mid] > sorted_arr[mid]:
                end = mid - 1
            else:
                start = mid + 1

    return start
