def remove_list_range(lists, start, end):

    def list_within_range(sublist):
        min_allowed = start + 1
        max_allowed = end - 1
        for num in sublist:
            if (num < min_allowed) or (num > max_allowed):
                return False
        return True

    # Filter out sublist that are outside the range
    result = [sublist for sublist in lists if list_within_range(sublist)]
    return result
