def find_closet(arr1, arr2, arr3, k1, k2, k3):
    k1_arr1 = arr1[k1]
    k2_arr2 = arr2[k2]
    k3_arr3 = arr3[k3]
    distances = []
    for i in range(len(arr1)):
        for j in range(len(arr2)):
            for l in range(len(arr3)):
                if i == k1 and j == k2 and l == k3:
                    continue
                distance = abs(arr1[i] - k1_arr1) + abs(arr2[j] - k2_arr2) + abs(arr3[l] - k3_arr3)
                distances.append((distance, arr1[i], arr2[j], arr3[l]))
    distances.sort()
    return distances[0]
