def find_closet(arr1, arr2, arr3, k1, k2, k3):    
    # Initialize the result with the first elements of each array
    result = (arr1[k1], arr2[k2], arr3[k3])
    for i in range(len(arr1)):
        for j in range(len(arr2)):
            for t in range(len(arr3)):
                if i == k1 or j == k2 or t == k3: 
                    continue  # Skip if the current element is part of the closest triplet
                curr_dist = abs(arr1[i] - arr2[j]) + abs(arr2[j] - arr3[t])
                # Update the result if the current distance is closer
                if curr_dist < sum([abs(x - result[0]) for x in result]):
                    result = (arr1[i], arr2[j], arr3[t])
    return tuple(result):  # Convert the tuple to a tuple
