def matrix_to_list(mat):
    # Initialize an empty list to store the flattened tuples
    result = []
    # Iterate through the list of tuples (outer loop)
    for inner_list in mat:
        # Iterate through each inner tuple (inner loop)
        for row in inner_list:
            # Extend the result list by appending the tuple row
            result.extend(row)
    # Return the flattened list
    return tuple(result)
