        return 0

    # Find increasing array
    increasing = []
    for num in arr:
        for i in range(len(increasing)):
            if num <= increasing[i]:
                break
        else:
            increasing.append(num)

    # Find decreasing array
    decreasing = []
    for num in reversed(arr):
        for i in range(len(decreasing)):
            if num <= decreasing[i]:
                break
        else:
            decreasing.append(num)

    # Find longest bitonic subsequence
    lbs_sequence = []
