def second_frequent(String_array):
    # Count the frequency of each string in the array
    frequency_dict = {}
    for string in String_array:
        if string in frequency_dict:
            frequency_dict[string] += 1
        else:
            frequency_dict[string] = 1

    # Find the strings with frequency greater than 1
    frequent_strings = [string for string, freq in frequency_dict.items() if freq > 1]

    # Sort the strings by frequency in descending order
    frequent_strings.sort(key=frequency_dict.get, reverse=True)

    # Return the second string in the sorted list (second frequent)
    return frequent_strings[1] if len(frequent_strings) > 1 else None
