def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def Sum(n):
    """Calculate the sum of all prime divisors of a given number."""
    prime_sum = 0
    while n > 1:
        if n % 2 == 0:
            prime_sum += 2
            while n % 2 == 0:
                n //= 2
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                prime_sum += i
                while n % i == 0:
                    n //= i
        if n > 2:
            prime_sum += n
    return prime_sum

