def find_Min_Swaps(input_array, length):
    total_swaps = 0
    for i in range(length-1):
        if input_array[i] != input_array[i+1]:
            left_count = right_count = 0
            left_idx = right_idx = i
            while left_idx >= 0 and input_array[left_idx] == input_array[i]:
                left_count += 1
                left_idx -= 1
            while right_idx < length and input_array[right_idx] == input_array[i+1]:
                right_count += 1
                right_idx += 1
            total_swaps += min(left_count, right_count-1)
    return total_swaps
