def min_cost(cost, m, n):
    # Initialize a 2D list with the same size as cost, filled with infinity
    path_cost = [[float('inf')] * (n + 1) for _ in range(m + 1)]
    path_cost[0][0] = cost[0][0]  # Set the cost of reaching (0, 0) to the cost at (0, 0)

    # Fill the first row and column of path_cost
    for i in range(1, m + 1):
        path_cost[i][0] = path_cost[i - 1][0] + cost[i][0]
    for j in range(1, n + 1):
        path_cost[0][j] = path_cost[0][j - 1] + cost[0][j]

    # Fill the rest of the path_cost table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            path_cost[i][j] = min(path_cost[i - 1][j], path_cost[i][j - 1]) + cost[i][j]

    return path_cost[m][n]  # Return the minimum cost to reach (m, n)
```

