def min_cost(cost, m, n):
    # Initialize the cost to reach the starting position with inf
    costo = [[float('inf')] * (n + 1)] * (m + 1)
    costo[0][0] = 0  # Base case: Starting point has a cost of 0

    # Iterate through all cells
    for i in range(m + 1):
        for j in range(n + 1):
            # Calculate cost from the top-left cell to the current cell
            if i > 0 and j > 0:
                costo[i][j] = min(costo[i][j], costo[i - 1][j] + cost[i][j - 1])
            elif i > 0:
                costo[i][j] = min(costo[i][j], costo[i - 1][j])
            elif j > 0:
                costo[i][j] = min(costo[i][j], costo[i][j - 1])

    # The minimum cost to reach the position (m, n)
    return costo[m][n]
```

