def coin_change(coins, target, n):
    # Create a list to store the number of ways to make each amount from 0 to target
    dp = [0] * (target + 1)
    dp[0] = 1  # There's one way to make 0 cents (do nothing)
    for i in range(n):
        for j in range(coins[i], target + 1):
            dp[j] += dp[j - coins[i]]  # Add the number of ways to make (j - coins[i])
    return dp[target]
