def maxAverageOfPath(matrix, n):
    # Initialize the board with the same size as the matrix
    board = [[0] * n for _ in range(n)]

    # Fill the board with the maximum path average
    for i in range(n):
        for j in range(n):
            if i == j:
                board[i][j] = matrix[i][j]  # Place the value directly on the diagonal
            else:
                max_avg = 0
                # Find the maximum average by adding values from left and right diagonals
                for k in range(-min(i+1, j+1), min(n-i, n-j)):
                    max_avg = max(max_avg, matrix[i+k][j-k] / (2 * k + 1))
                board[i][j] = max_avg * (2 * k + 1)  # Update the value at the diagonal

    # Calculate the total average of the filled board
    total_avg = sum(sum(row) for row in board) / (n * n)
    return total_avg
```

