def rencontres_number(nth, rotate):
    # Initialize the recurrence relation
    if rotate == 0:
        formula = lambda i, j: i * (n-th)
    elif rotate == 1:
        formula = lambda i, j: i * j
    elif rotate == 2:
        formula = lambda i, j: (i * j) - ((n-th) * (n-th))
    else:
        return "Invalid rotate value"

    # Calculate the nth rencontres number using recurrences
    m = (n // 2) + 1
    result = formula(0, m)
    for i in range(1, nth):
        total = result - formula(i, m)
        result = total + formula(i + 1, m)

    return result
