def sum_Of_product(n):
    # Define the binomial coefficient function
    def binomial_coefficient(x, y):
        if y > x:
            return 0
        if y == 0 or x == y:
            return 1
        return binomial_coefficient(x-1, y) + binomial_coefficient(x-1, y-1)

    # Calculate the sum of product of binomial coefficients
    sum_product = 0
    for i in range(1, n+1):
        for j in range(1, i+1):
            sum_product += binomial_coefficient(i, j)

    return sum_product
