def floor_Min(A, B, C):
    # Initialize the minimum value with the maximum possible value
    min_value = float('inf')

    # Iterate through all possible combinations of A, B, and C
    for i in range(A, min(B, C) + 1):
        for j in range(B, min(A, C) + 1):
            for k in range(C, max(A, B) + 1):
                # Calculate the floor value of the sum and update the minimum value if necessary
                min_value = min(min_value, max(i, j, k))

    # Return the minimum found value
