                dp[index + 1][skip_count][1] = num_list[index] + max(dp[index][skip_count][1], dp[index + 1][skip_count][0])

            # Value when a number is skipped
            if index >= 3:
                # Skip the current number, include the last two removed numbers
                dp[index + 1][skip_count][0] = max(dp[index + 1][skip_count][0], dp[index - 3][skip_count][1])

    return dp[len(num_list)][0][1]
