    if l > r:
        return None  # Array is empty or pointer out of bounds
    mid = (l + r) // 2
    if mid == 0:
        return nums[r] if nums[r] > nums[mid] else nums[mid]
    if nums[mid] > nums[mid - 1] and nums[mid] > nums[mid + 1]:
        return nums[mid]
    if nums[mid] < nums[mid - 1]:
        return find_Max(nums, l, mid - 1)
    else:
