def sum_Of_product(n):
    # Initialize the array for binomial coefficients
    C = [[0] * (n+1) for _ in range(n+1)]

    # Calculate the binomial coefficients
    for i in range(n+1):
        for j in range(min(i, n-i+1)):
            if j == 0 or i == j:
                C[i][j] = 1
            else:
                C[i][j] = C[i-1][j-1] + C[i-1][j]

    # Calculate sum of product of binomial coefficients
    return sum(C[i][i] * 2**i for i in range(1, n+1))
