def find_closet(arr1: List[int], arr2: List[int], arr3: List[int], x: int, y: int, z: int) -> Tuple[int, int, int]:
    def closest_element(arr: List[int], target: int) -> Tuple[int, int]:
        left, right = 0, len(arr) - 1
        min_diff = float('inf')
        closest_val = None
        while left <= right:
            mid = (left + right) // 2
            curr_diff = abs(target - arr[mid])
            if curr_diff < min_diff:
                min_diff = curr_diff
                closest_val = arr[mid]
            if target < arr[mid]:
                right = mid - 1
            elif target > arr[mid]:
                left = mid + 1
            else:
                return (arr[mid], arr[mid])
        return closest_val, closest_val + 1 if closest_val + 1 <= max(arr) and arr[closest_val + 1] <= z else arr[right], closest_val + 1 if closest_val + 1 <= max(arr) and arr[closest_val + 1] <= z else arr[right]

    closest_val1, closest_val2, closest_val3 = closest_element(arr1, x), closest_element(arr2, y), closest_element(arr3, z)
    return closest_val1, closest_val2, closest_val3
