```python
def find_kth(arr1, arr2, index1, index2, k):
    # Base case: if we are at the end of one of the arrays, return the element from the other array
    if index1 == len(arr1):
        return arr2[index2 + k - 1]
    if index2 == len(arr2):
        return arr1[index1 + k - 1]

    # If k is 1, return the smaller of the two elements
    if k == 1:
        return min(arr1[index1], arr2[index2])

    # Continue the process by calculating the remaining k - 1 elements
    # from the rest of the arrays
    if arr1[index1] < arr2[index2]:
        return find_kth(arr1, arr2, index1 + 1, index2, k - 1)
    else:
        return find_kth(arr1, arr2, index1, index2 + 1, k - 1)
```

