def find_kth(A, B, k1, k2, k):
    """
    Finds the kth element from two sorted arrays A and B.

    Parameters:
    A (list): The first sorted array.
    B (list): The second sorted array.
    k1 (int): The starting index in array A.
    k2 (int): The starting index in array B.
    k (int): The kth position to find in the combined array.

    Returns:
    int: The kth element.
    """
    if k1 == len(A):
        return B[k2 + k - 1]
    if k2 == len(B):
        return A[k1 + k - 1]
    if (k1 + k2) == k:
        return min(A[k1], B[k2])

    midA = k // 2 if k % 2 == 0 else (k + 1) // 2
    midB = (k - midA) // 2 if k % 2 == 0 else (k - midA + 1) // 2

    if A[midA] == B[midB]:
        return A[midA]

    if A[midA] > B[midB]:
        return find_kth(A, B, k1, midB - 1, k)
    else:
        return find_kth(A, B, midA - 1, k2, k)
