import numpy as np

def maxAverageOfPath(matrix, n):
    # Generate all possible paths of length n in a square grid
    paths = []
    for row in range(n):
        for col in range(n):
            if row == 0 and col == 0:
                continue
            path = [tuple(matrix[row][col])]
            for i in range(1, n):
                if row == 0 and col > 0:
                    path.append(tuple(matrix[row][col - 1]))
                elif row > 0 and col == 0:
                    path.append(tuple(matrix[row - 1][col]))
                elif row == n - 1 and col > 0:
                    path.append(tuple(matrix[row][col - 1]))
                elif row > 0 and col == n - 1:
                    path.append(tuple(matrix[row - 1][col]))
            paths.append(path)

    # Calculate the average of each path
    averages = []
    for path in paths:
        total = np.sum(path)
        average = total / len(path)
        averages.append(average)

    # Return the maximum average found
    return max(averages)
