def maxAverageOfPath(matrix, n):
    total = 0
    for i in range(n):
        for j in range(n):
            total += matrix[i][j]
    pathSum = 0
    maxAverage = 0
    for i in range(n):
        for j in range(n):
            pathSum = matrix[i][j]
            for p in range(i+1, n):
                pathSum += matrix[p][j]
            for q in range(j+1, n):
                pathSum += matrix[i][q]
            for r in range(i+1, n):
                for s in range(j+1, n):
                    pathSum += matrix[r][s]
                    maxAverage = max(maxAverage, pathSum / 5)
    return maxAverage
