def get_coordinates(coord):
    """Extracts all the adjacent coordinates of the given coordinate tuple."""
    rows, cols = len(coord), len(coord[0])
    adj_coords = []
    for r in range(rows):
        for c in range(cols):
            # Possible adjacent coordinates
            if r > 0:
                adj_coords.append([r-1, c])
            if c > 0:
                adj_coords.append([r, c-1])
            if r + 1 < rows:
