def min_coins(coins, val, W):
    M = len(coins)
    dp = [[0 for _ in range(W + 1)] for _ in range(M + 1)]

    for i in range(1, M + 1):
        for j in range(1, W + 1):
            if coins[i - 1] <= j:
                dp[i][j] = min(dp[i - 1][j], dp[i][j - coins[i - 1]] + 1)
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[M][W]
