import math

def sum_of_square(n):
    """
    Calculate the sum of squares of binomial co-efficients for a given n.

    Args:
        n (int): The value to calculate the coefficient for.

    Returns:
        int: The sum of squares of binomial co-efficients.
    """
    if n == 0:
        return 1
    if n % 2 == 0:
        return (2**n) * (math.factorial(n) // (math.factorial(n//2) ** 2))
    else:
        return 2**(n+1) - (2**n) * (math.factorial(n-1) // (math.factorial((n-1)//2)) ** 2)

# Test the function
