        if k == 0 or k == 1:
            return 1
        return k * factorial(k-1)

    bell = [[0 for _ in range(n+1)] for _ in range(n+1)]

    for i in range(n+1):
        bell[i][0] = 1

    for i in range(1, n+1):
        for j in range(1, i+1):
            bell[i][j] = bell[i-1][j-1] + i * bell[i][j-1]

    return bell[n][n]
