import functools

def max_sum_pair_diff_lessthan_K(arr, k, diff):
    # Sort the array to enable using the two pointers technique
    arr.sort(reverse=True)
    while arr and arr[-1] > diff:
        arr.pop()

    total_sum = 0
    left, right = 0, len(arr) - 1

    while right > left:
        if abs(arr[left] + arr[right] - k) <= diff:
            total_sum += (arr[left] + arr[right])
            left += 1
            right -= 1
        elif arr[left] + arr[right] - k > diff:
            right -= 1
        else:
            left += 1

    return total_sum
