def max_sum_pair_diff_lessthan_K(nums, K, k):
    nums.sort()
    left, right = 0, len(nums) - 1
    max_sum = 0
    while left < right:
        current_sum = nums[left] + nums[right]
        if current_sum > K:
            right -= 1
        else:
            if current_sum > max_sum and current_sum <= k:
                max_sum = current_sum
            left += 1
    return max_sum
```

