    def find LCS Dyn():
        # Create a 2D DP table to store lengths of longest common subsequences
        table = [[0] * (n + 1) for _ in range(m + 1)]

        # Build the DP table
        for i in range(m + 1):
            for j in range(n + 1):
                if i == 0 or j == 0:
                    table[i][j] = 0
                elif str1[i - 1] == str2[j - 1]:
                    table[i][j] = table[i - 1][j - 1] + 1
                else:
                    table[i][j] = max(table[i - 1][j], table[i][j - 1])

        # The length of the longest common subsequence is stored in table[m][n]
        return table[m][n]

    # Find the length of the shortest common supersequence (LCS DS) + the lengths of both input strings
    result = find LCS Dyn() + m + n - table[m][n]

