def super_seq(A, B, n, m):
    # Create a 2D array with initial values
    table = [[1] * (m + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            # If characters match
            if A[i - 1] == B[j - 1]:
                # Add 1 to the count of matches
                table[i][j] = table[i - 1][j - 1] + 1
            else:
                # Take the maximum of the left and top cells
                table[i][j] = max(table[i - 1][j], table[i][j - 1])

    # The total length of the shortest supersequence is the sum of lengths of A and B minus the length of the longest common subsequence
    return n + m - table[n][m]
