def super_seq(str1, str2, len1, len2):
    # Create a DP table to store lengths of common subsequences
    dp = [[0 for _ in range(len2 + 1)] for _ in range(len1 + 1)]

    # Build the DP table
    for i in range(1, len1 + 1):
        for j in range(1, len2 + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # The length of the shortest common supersequence is len1 + len2 - dp[len1][len2]
    return len1 + len2 - dp[len1][len2]
```

