def unique_sublists(main_list):
    # Create an empty dictionary to store unique sublists
    unique_dict = {}
    # Iterate through each sub-list in the main list
    for sublist in main_list:
        # Convert the sub-list to a tuple and check if it's already in the dictionary
        if tuple(sublist) in unique_dict:
            # If the sub-list is already in the dictionary, increment the count
            unique_dict[tuple(sublist)] += 1
        else:
