def count_Rotation(A, key):
    """Returns the number of rotations required in the sorted array A """
    start = 0
    end = len(A) - 1

    while start <= end:
        mid = (start + end) // 2                            # Calculate middle index

        # If mid is the first element
        if A[mid] <= A[mid + 1]: 
            if A[mid] > A[start]:
                return 0                               # No rotations, first element is the pivot
            else:
                start = mid + 1                               # Continue search on the right half

        # If mid is the last element
        elif A[mid] >= A[mid - 1]:
            if A[mid] > A[end]:
                return 1                               # One rotation, last element is the pivot
            else:
                end = mid - 1                               # Continue search on the left half

        # If mid is not the pivot
        else:
            start += 1                               # One rotation has ended, move to the next element

    raise ValueError("Array is not sorted")
