def min_cost(cost, m, n):
    # Define the limit of the array
    limit = len(cost) - 1

    # If the position does not exist within the array bounds, return infinity
    if 0 > m or m > limit or 0 > n or n > limit:
        return float('inf')

    # Base case: if we are at the starting position (0, 0)
    if m == 0 and n == 0:
        return cost[0][0]

    # Recursive cases: from above, below, left, right
    else:
        return cost[m][n] + min(min_cost(cost, m - 1, n), min_cost(cost, m + 1, n), min_cost(cost, m, n - 1), min_cost(cost, m, n + 1))
