def max_sum_of_three_consecutive(nums, n):
    if n == 0:
        return 0

    # Base cases
    if n == 1:
        return max(nums[0], 0)
    if n == 2:
        return max(nums[0] + nums[1], 0)

    max_sum = [
        max(nums[0], nums[1]),
        max(nums[0] + nums[1], 0),
        max(nums[0] + nums[2], max(nums[0], nums[1]))
    ]

    # Iterate through the array to find the maximum sum of three consecutive elements
    for i in range(3, n):
        local_max = max(
            nums[i] + nums[i-2] + nums[i-3],
            max_sum[i-1] + nums[i],
            local_max
        )
        max_sum.append(local_max)

    # The maximum sum of consecutive three elements is the element at index n-1
    return max_sum[n-1]
