def dealnnoy_num(n, k):
    # Initialize the base cases
    if n == 0:
        return 0
    if k == 0:
        return 1

    # Use dynamic programming to calculate the nth delannoy number
    dp = [[0 for _ in range(k + 1)] for _ in range(n + 1)]

    # Base cases
    dp[0][0] = 1

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(k + 1):
            if j == i:
                dp[i][j] = 1
            else:
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1] + dp[i - 1][j - 1]

    return dp[n][k]
```

