def dealnnoy_num(n, k):
    # Initialize the base cases
    if n == 0 or k == 0:
        return 1
    elif n == 1:
        return 1
    elif k == 1:
        return 2
    elif k == 2:
        return 4

    # Helper function to calculate delannoy numbers
    def helper(i, j):
        if i == 0 or j == 0:
            return 1
        elif i == 1:
            return 2
        elif j == 2:
            return 4
        else:
            return helper(i - 1, j - 1) + helper(i - 2, j - 2) + helper(i, j - 1)

    # Calculate the nth delannoy number
    return helper(n - 1, k - 1)
