def toggle_F_and_L_bits(num):
    # Extract the first and last bits
    first_bit = (num & 1) == 1
    last_bit = (num & (1 << 31)) != 0

    # Toggle first and last bits
    if first_bit:
        new_num = num ^ 1
    else:
        new_num = num

    if last_bit:
        new_num = new_num ^ (1 << 31)
    else:
        new_num = new_num

