def find_First_Missing(nums, low, high):
  # Check if the first element is missing
  if nums[0] != low:
    return low

  # Check if the last element is missing
  if nums[high] != high + 1:
    return high + 1

  while low <= high:
    mid = low + (high - low) // 2

    # Check if mid is missing
    if mid != nums[mid]:
      # If mid is missing, return it
      return mid

    # If mid is present, search in the left or right half accordingly
    elif nums[mid] > mid + 1:
      high = mid - 1
    else:
      low = mid + 1

  # If no missing number is found, return the length of the array
  return high + 1
