    if k == 4:
        return dealnnoy_num(n, k-1) * 2 + dealnnoy_num(n, k-2)

    # Recursive case: sum of three delannoy numbers
    return dealnnoy_num(n, k-1) + dealnnoy_num(n-1, k-1) + dealnnoy_num(n-2, k)

