def maximum_segments(y1, y2, y3, n):
    # Helper function to find the maximum number of segments for a given length
    def helper(m):
        max_segment = 0
        # Loop through all possible segment lengths that can be formed with the given length
        for a in range(0, n // y1, y1):
            for b in range(0, (n - a) // y2, y2):
                if (n - a - b) % y3 == 0:
                    max_segment += 1
        return max_segment

