    if A[mid] >= A[mid + 1] and A[mid] >= A[mid - 1]:
        return A[mid]

    # if the right half of the array is sorted and the first element of the right half is greater than the last element of the left half,
    # then the maximum element is in the right half
    if A[mid + 1] <= A[r]:
        return find_Max(A, mid + 1, r)

