def rencontres_number(n, left):
    if n < 1:
        raise ValueError("n must be a positive integer")

    if left < 0:
        raise ValueError("left must be a non-negative integer or 0 if it is to count all possible left arrangements")

    if left > 0 and left > n // 2:
        raise ValueError("left cannot be greater than n//2 if n is odd")

    result = 1
    for i in range(1, n + 1):
        if i <= n // 2:
            result *= i
        else:
            result //= i

    return result
