def rencontres_number(n, k):
    # Initialize the matrix
    m = [[0 for _ in range(k+1)] for _ in range(k+1)]

    # Base cases
    for i in range(1, k+1):
        for j in range(1, k+1):
            if i == j:
                m[i][j] = 0
            elif i == 1:
                m[i][j] = j
            elif j == 1:
                m[i][j] = i
            else:
                m[i][j] += m[i-1][j-1] + m[i-1][j]

    # Calculate the n-th rencontres number
    return m[n][k]
